"use client";

import "./tabs.css";

import type React from "react";

import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import { cn } from "tailwind-variants";

import { TabsContext, useTabsContext } from "./tabs.context";
import { tabsVariants, type TabsVariants } from "./tabs.variants";

export type TabsProps = TabsVariants & React.ComponentProps<typeof BaseTabs.Root>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/tabs/content.md
 */
export const TabsRoot = ({ children, className, variant, size, ...props }: TabsProps) => {
  const slots = tabsVariants({ variant, size });

  return (
    <TabsContext.Provider value={{ slots }}>
      <BaseTabs.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseTabs.Root>
    </TabsContext.Provider>
  );
};

export type TabsListProps = React.ComponentProps<typeof BaseTabs.List>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/tabs/content.md
 */
export const TabsList = ({ className, ...props }: TabsListProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.List className={cn(slots.list(), className)} {...props} />;
};

export type TabsTabProps = React.ComponentProps<typeof BaseTabs.Tab>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/tabs/content.md
 */
export const TabsTab = ({ className, ...props }: TabsTabProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.Tab className={cn(slots.tab(), className)} {...props} />;
};

export type TabsIndicatorProps = React.ComponentProps<typeof BaseTabs.Indicator>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/tabs/content.md
 */
export const TabsIndicator = ({ className, ...props }: TabsIndicatorProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.Indicator className={cn(slots.indicator(), className)} {...props} />;
};

export type TabsPanelProps = React.ComponentProps<typeof BaseTabs.Panel>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/tabs/content.md
 */
export const TabsPanel = ({ className, ...props }: TabsPanelProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.Panel className={cn(slots.panel(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const tabsVariants = tv({
  slots: {
    root: "tabs",
    list: "tabs__list",
    tab: "tabs__tab",
    indicator: "tabs__indicator",
    panel: "tabs__panel",
  },
  variants: {
    variant: {
      default: {
        list: "border-b border-border gap-1",
        tab: "data-active:text-foreground pb-2 font-medium",
        indicator: "bottom-0 h-0.5 bg-primary transition-all duration-200",
      },
      pills: {
        list: "bg-muted p-1 rounded-lg gap-1",
        tab: "rounded-md px-3 py-1.5 data-active:bg-background data-active:text-foreground data-active:shadow-xs",
        indicator: "bg-background rounded-md shadow-xs transition-all duration-200",
      },
      underline: {
        list: "border-b border-border gap-4",
        tab: "pb-2 border-b-2 border-transparent data-active:border-primary data-active:text-primary font-medium",
      },
    },
    size: {
      sm: {
        tab: "text-xs px-2.5 py-1",
        panel: "p-3 text-xs",
      },
      md: {
        tab: "text-sm px-3.5 py-1.5",
        panel: "p-4 text-sm",
      },
      lg: {
        tab: "text-base px-4 py-2",
        panel: "p-6 text-base",
      },
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
});

export type TabsVariants = VariantProps<typeof tabsVariants>;

"use client";

import { createContext, useContext } from "react";

import { tabsVariants } from "./tabs.variants";

export type TabsContext = {
  slots: ReturnType<typeof tabsVariants>;
};

export const TabsContext = createContext<TabsContext | null>(null);

export const useTabsContext = () => {
  const context = useContext(TabsContext);
  return context ?? { slots: tabsVariants() };
};

.tabs {
  @apply flex w-full flex-col text-foreground;
}

.tabs__list {
  @apply relative flex items-center select-none;
}

.tabs__tab {
  @apply inline-flex items-center justify-center cursor-pointer whitespace-nowrap text-muted-foreground transition-colors outline-none focus-visible:outline-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50;
}

.tabs__indicator {
  @apply absolute z-0;
}

.tabs__panel {
  @apply mt-2 outline-none focus-visible:outline-2 focus-visible:outline-ring;
}

import { TabsIndicator, TabsList, TabsPanel, TabsRoot, TabsTab } from "./tabs";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/tabs/content.md
 */
export const Tabs = {
  Indicator: TabsIndicator,
  List: TabsList,
  Panel: TabsPanel,
  Root: TabsRoot,
  Tab: TabsTab,
};

export { TabsIndicator, TabsList, TabsPanel, TabsRoot, TabsTab };

export type {
  TabsIndicatorProps,
  TabsListProps,
  TabsPanelProps,
  TabsProps,
  TabsTabProps,
} from "./tabs";
export { TabsContext, useTabsContext } from "./tabs.context";
export { type TabsVariants, tabsVariants } from "./tabs.variants";
